```java
// ─── File: src/main/java/com/bank/diamond/model/TradingService.java ───
// Extends ONE class + implements TWO interfaces with conflicting defaults
package com.bank.diamond.model;

import com.bank.diamond.capability.*;

public class TradingService extends BaseService implements Tradable, Auditable {

    public TradingService() {
        super("Trading Service");
    }

    // ═══ Implement abstract methods from both interfaces ═══
    @Override
    public void executeTrade(String symbol, int quantity) {
        System.out.println("Executed: " + quantity + " shares of " + symbol);
    }

    @Override
    public String generateAuditReport() {
        return "Audit report for " + getServiceName() + " on " + getMarket();
    }

    // ═══ CONFLICT RESOLUTION: getMarket() exists in BOTH interfaces ═══
    @Override
    public String getMarket() {
        // MUST override — compiler error without this!
        // "class TradingService inherits unrelated defaults for getMarket()"
        // Three resolution strategies:
        String tradableMarket = Tradable.super.getMarket();  // "NSE"
        String auditableMarket = Auditable.super.getMarket();  // "BSE"
        return tradableMarket + " + " + auditableMarket;  // "NSE + BSE" — combined!
    }

    // ═══ getServiceType(): BaseService.getServiceType() WINS over interface defaults ═══
    // NO override needed! Class method wins over both Tradable.getServiceType() and Auditable.getServiceType()
    // BaseService.getServiceType() → "BASE_SERVICE"
    // Tradable default: "TRADING" ← IGNORED (class wins)
    // Auditable default: "AUDIT" ← IGNORED (class wins)
}
```

```java
// ─── File: src/test/java/com/bank/diamond/DiamondProblemTest.java ───
package com.bank.diamond;

import com.bank.diamond.capability.*;
import com.bank.diamond.model.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class DiamondProblemTest {

    TradingService service = new TradingService();

    // ═══ Multiple interface implementation works ═══
    @Test
    void multipleInterfacesImplemented() {
        assertThat(service).isInstanceOf(Tradable.class);
        assertThat(service).isInstanceOf(Auditable.class);
        assertThat(service).isInstanceOf(BaseService.class);
        // Extends ONE class + implements TWO interfaces ✅
    }

    // ═══ Conflicting default resolved by class override ═══
    @Test
    void conflictingDefaultResolved() {
        assertThat(service.getMarket()).isEqualTo("NSE + BSE");
        // Both interfaces had getMarket(). Class resolved the conflict.
    }

    // ═══ InterfaceName.super.method() delegates to specific interface ═══
    @Test
    void canDelegateToSpecificInterface() {
        // The TradingService.getMarket() uses:
        // Tradable.super.getMarket() → "NSE"
        // Auditable.super.getMarket() → "BSE"
        // Combined: "NSE + BSE"
        assertThat(service.getMarket()).contains("NSE").contains("BSE");
    }

    // ═══ Class method wins over interface defaults ═══
    @Test
    void classMethodWinsOverInterfaceDefaults() {
        assertThat(service.getServiceType()).isEqualTo("BASE_SERVICE");
        // BaseService.getServiceType() wins over:
        //   Tradable.getServiceType() → "TRADING" (ignored!)
        //   Auditable.getServiceType() → "AUDIT" (ignored!)
        // Rule: class > interface default
    }

    // ═══ No diamond problem — class resolves everything ═══
    @Test
    void noDiamondProblem() {
        // Multiple class inheritance would create ambiguity (diamond problem).
        // Multiple interface implementation: class resolves conflicts explicitly.
        // No ambiguity. No silent wrong behavior. Compiler forces resolution.
        service.executeTrade("RELIANCE", 100);  // from Tradable
        String report = service.generateAuditReport();  // from Auditable
        assertThat(report).contains("Trading Service").contains("NSE + BSE");
    }

    // ═══ Without override of conflicting default → compile error ═══
    @Test
    void conflictMustBeResolvedOrCompileError() {
        // If TradingService did NOT override getMarket():
        // COMPILE ERROR: "class TradingService inherits unrelated defaults for getMarket()"
        // Java FORCES you to resolve. No silent ambiguity. ✅
        assertThat(true).isTrue();
    }
}
```
